using W=System.Windows;
using C=System.Windows.Controls;
using U=VelvetVoice.UiControls;
namespace CombinedStudio;
internal sealed class CrosshairLibrary:C.StackPanel,IDisposable {
 readonly CrosshairStore store;readonly Action<CrosshairDesign> select;readonly bool fixture;
 readonly C.ComboBox game=new(){ItemsSource=new[]{"Valorant","Fortnite","Counter-Strike","Built-in designs"},SelectedIndex=0,MinWidth=170,MinHeight=40,Margin=new W.Thickness(0,0,12,12)};
 readonly C.ComboBox sort=new(){ItemsSource=new[]{"Top rated","Name","Creator"},SelectedIndex=0,MinWidth=130,MinHeight=40,Margin=new W.Thickness(0,0,12,12)};
 readonly C.TextBox search=new(){MinWidth=180,MinHeight=40,Margin=new W.Thickness(0,0,12,12),ToolTip="Search crosshair name or creator"};
 readonly C.WrapPanel tiles=new();readonly C.TextBlock count=U.Text("",12,U.Muted);readonly C.TextBlock status=U.Text("",12,U.Muted);readonly C.Button previous,next;readonly C.Expander browse;
 CancellationTokenSource previewLoad=new();int page,selectionGeneration;bool disposed;
 internal CrosshairLibrary(CrosshairStore store,Action<CrosshairDesign> select,bool fixture){this.store=store;this.select=select;this.fixture=fixture;
  Children.Add(U.Text("Game crosshair library",20));Children.Add(U.Text("Complete public catalog snapshot · "+CrosshairCommunity.Catalog.Length.ToString("N0")+" community uploads. Designs download when previewed or selected and stay cached locally.",12,U.Muted));
  Children.Add(U.Text("Community uploads render their resting image and model layers. GIFs use the first frame; firing, recoil and ammo animations are not reproduced. Some layer formats may be unsupported.",12,U.Muted));
  var body=new C.StackPanel();var filters=new C.WrapPanel{Margin=new W.Thickness(0,12,0,0)};filters.Children.Add(game);filters.Children.Add(sort);filters.Children.Add(search);W.Automation.AutomationProperties.SetName(search,"Search crosshair name or creator");body.Children.Add(filters);body.Children.Add(count);body.Children.Add(tiles);var navigation=new C.WrapPanel();previous=Button("Previous",()=>{page--;Render();});next=Button("Next",()=>{page++;Render();});navigation.Children.Add(previous);navigation.Children.Add(next);body.Children.Add(navigation);body.Children.Add(status);browse=new(){Header="Browse Valorant, Fortnite and Counter-Strike",Foreground=U.Ink,Content=body};Children.Add(browse);
  game.SelectionChanged+=(_,_)=>{page=0;Render();};sort.SelectionChanged+=(_,_)=>{page=0;Render();};search.TextChanged+=(_,_)=>{page=0;Render();};browse.Expanded+=(_,_)=>Render();browse.Collapsed+=(_,_)=>previewLoad.Cancel();IsVisibleChanged+=(_,_)=>{if(IsVisible&&browse.IsExpanded)Render();else{selectionGeneration++;previewLoad.Cancel();}};Render();
 }
 C.Button Button(object text,Action action){var button=new C.Button{Content=text,MinHeight=38,Padding=new W.Thickness(10,5,10,5),Margin=new W.Thickness(0,8,10,8)};button.Click+=(_,_)=>action();return button;}
 void Render(){if(disposed)return;previewLoad.Cancel();previewLoad.Dispose();previewLoad=new();var token=previewLoad.Token;tiles.Children.Clear();string category=(string)game.SelectedItem;string query=search.Text.Trim();
  if(category=="Built-in designs"){var builtins=CrosshairStore.BuiltIn().Where(x=>x.Name.Contains(query,StringComparison.OrdinalIgnoreCase)).ToArray();count.Text=builtins.Length+" built-in designs";previous.IsEnabled=next.IsEnabled=false;foreach(var entry in builtins){var content=new C.StackPanel();content.Children.Add(new CrosshairView{FitPreview=true,Design=entry.Design,Width=140,Height=80});content.Children.Add(U.Text(entry.Name,12));tiles.Children.Add(Button(content,()=>select(entry.Design.Copy())));}return;}
  var entriesQuery=CrosshairCommunity.Catalog.Where(x=>x.Games.Contains(category)&&(x.Name.Contains(query,StringComparison.OrdinalIgnoreCase)||x.Creator.Contains(query,StringComparison.OrdinalIgnoreCase)));var entries=(sort.SelectedIndex switch{1=>entriesQuery.OrderBy(x=>x.Name,StringComparer.OrdinalIgnoreCase),2=>entriesQuery.OrderBy(x=>x.Creator,StringComparer.OrdinalIgnoreCase),_=>entriesQuery.OrderByDescending(x=>x.Rating).ThenBy(x=>x.Id)}).ToArray();int pages=Math.Max(1,(entries.Length+23)/24);page=Math.Clamp(page,0,pages-1);count.Text=category+" · "+entries.Length.ToString("N0")+" results · page "+(page+1)+" / "+pages;previous.IsEnabled=page>0;next.IsEnabled=page+1<pages;
  foreach(var entry in entries.Skip(page*24).Take(24)){var design=entry.Preset.Design;var tile=new C.StackPanel{Width=160};var view=new CrosshairView{FitPreview=true,Design=design,ImageFolder=store.Folder,Width=160,Height=85};var caption=U.Text(entry.Name,12);caption.TextTrimming=W.TextTrimming.CharacterEllipsis;var creator=U.Text("by "+entry.Creator,11,U.Muted);creator.TextTrimming=W.TextTrimming.CharacterEllipsis;var readiness=U.Text(File.Exists(Path.Combine(store.Folder,design.ImageFile))?"Cached":"Preview loads on opening",10,U.Muted);tile.Children.Add(view);tile.Children.Add(caption);tile.Children.Add(creator);tile.Children.Add(readiness);var column=new C.StackPanel{Margin=new W.Thickness(0,0,12,12)};column.Children.Add(Button(tile,()=>Choose(entry)));column.Children.Add(Button("Source ↗",()=>System.Diagnostics.Process.Start(new System.Diagnostics.ProcessStartInfo(entry.Url){UseShellExecute=true})));tiles.Children.Add(column);if(!fixture&&IsVisible&&browse.IsExpanded)_=LoadPreview(design,view,readiness,token);}
 }
 async Task LoadPreview(CrosshairDesign design,CrosshairView view,C.TextBlock label,CancellationToken token){try{label.Text="Loading…";await CrosshairCommunity.Ensure(design,store.Folder,token);token.ThrowIfCancellationRequested();_ = CrosshairCommunityDrawing.Load(Path.Combine(store.Folder,design.ImageFile));view.InvalidateVisual();label.Text="Ready · resting layers";}catch(OperationCanceledException){}catch(Exception error){if(!token.IsCancellationRequested){label.Text="Preview unavailable";label.ToolTip=error.GetBaseException().Message;}}}
 async void Choose(CommunityCrosshair entry){int generation=++selectionGeneration;status.Text="Loading "+entry.Name+"…";try{var design=entry.Preset.Design;await CrosshairCommunity.Ensure(design,store.Folder);_ = CrosshairCommunityDrawing.Load(Path.Combine(store.Folder,design.ImageFile));if(disposed||generation!=selectionGeneration)return;select(design);status.Text="Selected "+entry.Name+" by "+entry.Creator+" · resting layers. Save design to keep a favorite.";}catch(Exception error){if(!disposed&&generation==selectionGeneration)status.Text="Could not load "+entry.Name+": "+error.GetBaseException().Message;}}
 public void Dispose(){disposed=true;selectionGeneration++;previewLoad.Cancel();previewLoad.Dispose();}
 internal void ShowGame(string category){game.SelectedItem=category;page=0;Render();}
 internal void Verify(string fixtures){if(Directory.Exists(fixtures)){Directory.CreateDirectory(store.Folder);foreach(var file in Directory.EnumerateFiles(fixtures,"community-*.json")){string filename=Path.GetFileName(file);if(!CrosshairCommunity.Catalog.Any(x=>x.Preset.Design.ImageFile==filename))continue;_ = CrosshairCommunityDrawing.Load(file);File.Copy(file,Path.Combine(store.Folder,filename),true);}}browse.IsExpanded=true;foreach(string category in CrosshairCommunity.Games){game.SelectedItem=category;Render();if(tiles.Children.Count!=24||!count.Text.StartsWith(category+" · "))throw new Exception("Community gallery pagination failed: "+category);page=1;Render();if(!previous.IsEnabled)throw new Exception("Community pagination did not advance.");}search.Text="YAIOpc-no-match-"+Guid.NewGuid();if(tiles.Children.Count!=0||next.IsEnabled)throw new Exception("Community search did not filter.");search.Text="";game.SelectedItem="Built-in designs";if(tiles.Children.Count!=32)throw new Exception("Built-in gallery was lost.");game.SelectedItem="Fortnite";page=0;Render();}
}
